-- Person-centred support plan template
-- Source of truth: contracts/support-plan.ts
-- Runtime ensure: api/lib/ensure-support-plan-template.ts

update public.document_templates
set active = false
where kind = 'support_plan' and active = true
  and (structure->>'format' is distinct from 'person_centred_v1');

insert into public.document_templates (kind, version, name, structure, active)
select 'support_plan', 2, 'Support plan - person-centred', '{"format":"person_centred_v1","sections":[{"key":"about_me","title":"About me","required":true,"layout":"fields","guidance":"Who I am, what matters to me, my story and preferences.","fields":[{"key":"whoIAm","label":"Who I am","type":"textarea","span":"full","required":true},{"key":"whatMatters","label":"What matters to me","type":"textarea","span":"full","required":true},{"key":"likesDislikes","label":"Likes and dislikes","type":"textarea","span":"full"},{"key":"routines","label":"My routines and how I like my day","type":"textarea","span":"full"},{"key":"communication","label":"How I communicate","type":"textarea","span":"full"}]},{"key":"outcomes","title":"Outcomes I want to achieve","required":true,"layout":"fields","guidance":"What good looks like for me - goals we are working towards.","fields":[{"key":"outcomes","label":"Outcomes / goals","type":"textarea","span":"full","required":true},{"key":"howWeKnow","label":"How we will know we are succeeding","type":"textarea","span":"full"},{"key":"myPriorities","label":"My priorities right now","type":"textarea","span":"full"}]},{"key":"how_supported","title":"How I want to be supported","required":true,"layout":"fields","guidance":"The way carers should work with me - dignity, pace, language, involvement.","fields":[{"key":"supportStyle","label":"How I want to be supported","type":"textarea","span":"full","required":true},{"key":"do","label":"Please do","type":"textarea","span":"half"},{"key":"dont","label":"Please don''t","type":"textarea","span":"half"},{"key":"involvement","label":"How I want to be involved in decisions","type":"textarea","span":"full"},{"key":"carerNotes","label":"Notes for carers","type":"textarea","span":"full"}]},{"key":"independence_daily_living","title":"Independence and daily living","required":true,"layout":"fields","guidance":"What I can do myself, where I need a prompt or a hand.","fields":[{"key":"iCanDo","label":"Things I can do myself","type":"textarea","span":"full","required":true},{"key":"iNeedHelpWith","label":"Things I need support with","type":"textarea","span":"full","required":true},{"key":"prompts","label":"Prompts that work for me","type":"textarea","span":"full"},{"key":"equipment","label":"Equipment / adaptations that help","type":"textarea","span":"full"}]},{"key":"health_wellbeing","title":"Health & wellbeing","required":true,"layout":"fields","guidance":"Health, mood, sleep and what keeps me well (support-focused - clinical detail sits in the care plan).","fields":[{"key":"feelingWell","label":"What helps me feel well","type":"textarea","span":"full","required":true},{"key":"healthSupport","label":"Health support I want from carers","type":"textarea","span":"full"},{"key":"mood","label":"Mood and emotional wellbeing","type":"textarea","span":"full"},{"key":"sleep","label":"Sleep and rest","type":"textarea","span":"half"},{"key":"escalate","label":"When to escalate / who to call","type":"textarea","span":"half"}]},{"key":"community_relationships","title":"Community and relationships","required":false,"layout":"fields","guidance":"People, places and activities that matter to me.","fields":[{"key":"importantPeople","label":"Important people in my life","type":"textarea","span":"full"},{"key":"community","label":"Community, clubs and activities","type":"textarea","span":"full"},{"key":"faithCulture","label":"Faith, culture and identity","type":"textarea","span":"full"},{"key":"stayingConnected","label":"How I stay connected","type":"textarea","span":"full"}]},{"key":"working_not_working","title":"What''s working / not working","required":true,"layout":"fields","guidance":"Honest picture of what is going well and what needs to change.","fields":[{"key":"working","label":"What''s working","type":"textarea","span":"full","required":true},{"key":"notWorking","label":"What''s not working","type":"textarea","span":"full","required":true},{"key":"changesWanted","label":"Changes I want","type":"textarea","span":"full"}]},{"key":"positive_risk","title":"Positive risk-taking","required":true,"layout":"fields","guidance":"Risks I choose to take, and how we support me safely to do so.","fields":[{"key":"choices","label":"Choices / risks I want to take","type":"textarea","span":"full","required":true},{"key":"howSupported","label":"How we support those choices safely","type":"textarea","span":"full","required":true},{"key":"agreedLimits","label":"Agreed limits / what we will not do","type":"textarea","span":"full"}]},{"key":"contingency","title":"Contingency plans","required":true,"layout":"fields","guidance":"What happens if I am unwell, carers cannot attend, or something goes wrong.","fields":[{"key":"ifUnwell","label":"If I am unwell","type":"textarea","span":"full","required":true},{"key":"ifCarerCannotAttend","label":"If a carer cannot attend","type":"textarea","span":"full","required":true},{"key":"emergency","label":"Emergency contacts and actions","type":"textarea","span":"full","required":true},{"key":"outOfHours","label":"Out-of-hours arrangement","type":"textarea","span":"full"}]},{"key":"support_visits","title":"Support visits","required":true,"layout":"visits","guidance":"When support visits happen and what each visit is for (morning / lunch / tea / bed / other)."},{"key":"review","title":"Review","required":true,"layout":"fields","guidance":"How and when we review this support plan with me.","fields":[{"key":"reviewDate","label":"Next review date","type":"date","span":"half","required":true},{"key":"reviewWith","label":"Who is involved in the review","type":"text","span":"half"},{"key":"howReviewed","label":"How we will review (meeting, call, visit)","type":"textarea","span":"full"},{"key":"reviewNotes","label":"Review notes / agreements","type":"textarea","span":"full"}]}]}'::jsonb, true
where not exists (
  select 1 from public.document_templates
  where kind = 'support_plan' and version = 2
);

